/**
 * Annotations: drawing a box on a picture, and where that box lands (M6).
 *
 * One property carries this suite, and it is the one that is subtly wrong in every naive implementation.
 *
 * **The image is `object-contain`.** Its element's bounding box includes empty bands on two sides — a 2:1
 * picture in a squarer container has grey above and below — so normalising a drag against the *element* puts
 * every mark off by the height of those bands. Migration 0037's column comment warns about it, and the only way
 * to catch it is to draw on a genuinely letterboxed image and check the numbers.
 *
 * So the fixture is a real 200×100 PNG, served as a real response so `naturalWidth` and `naturalHeight` are
 * meaningful, rendered in a container that is not 2:1. A drag over the middle of the *picture* must come back
 * as the middle of the picture — not the middle of the element.
 *
 * The rest is what makes the feature usable: fractions rather than pixels on the wire, a click that is not a
 * drag deselecting rather than creating a one-pixel annotation, and an honest statement about the keyboard.
 */
import { expect, test } from './fixtures';
import { type Page } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

const WCAG_21_AA = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'];
const ASSET = '00000000-0000-4000-8000-000000000000';

/** A 200×100 PNG — 2:1, so it letterboxes vertically in the lightbox's container. */
const WIDE_PNG = Buffer.from(
	'',
	'base64'
);

function person(name = 'Ada') {
	return { id: 'p-ada', name, email: 'ada@example.com' };
}

function comment(overrides: Record<string, unknown> = {}) {
	return {
		id: 'c1111111-1111-4111-8111-111111111111',
		asset_id: ASSET,
		author: person(),
		body: 'the logo is the old one',
		visibility: 'public',
		status: 'open',
		status_by: null,
		parent_id: null,
		recipients: [],
		created_at: '2026-08-23T09:00:00Z',
		edited_at: null,
		region: null,
		at_ms: null,
		...overrides
	};
}

function asset() {
	return {
		id: ASSET,
		filename: 'wide.png',
		mime: 'image/png',
		bytes: 41_866,
		width: 200,
		height: 100,
		tier: 'hot',
		rights_state: 'allowed',
		provenance_state: 'none',
		thumbnail_url: 'http://127.0.0.1:8099/d/thumb',
		preview_url: 'http://127.0.0.1:8099/d/preview',
		tag_confidence: null,
		is_favourite: false,
		average_stars: null,
		has_attachment: false,
		published_at: null,
		values: {},
		technical: {},
		duration_ms: null,
		page_count: null,
		color_space: 'sRGB',
		has_alpha: false,
		content_hash: 'a'.repeat(64),
		status: 'active',
		enrichment_state: 'done',
		legal_hold: false,
		release_at: null,
		expires_at: null,
		version_no: 1,
		created_at: '2026-08-01T09:00:00Z',
		updated_at: '2026-08-01T09:00:00Z',
		engagement: {
			asset_id: ASSET,
			average_stars: null,
			ratings: 0,
			is_favourite: false,
			is_watched: false
		}
	};
}

async function connect(page: Page, options: { comments?: Record<string, unknown>[] } = {}) {
	const recorder = { posted: [] as Record<string, unknown>[] };

	await page.addInitScript(() => {
		localStorage.setItem('damrs.api_key', 'damrs_test_key');
		localStorage.setItem('damrs.api_base', 'http://127.0.0.1:8099');
	});

	await page.route('**/127.0.0.1:8099/**', async (route) => {
		const url = new URL(route.request().url());
		const path = url.pathname;

		// A real image body, so naturalWidth and naturalHeight are real — the letterbox maths depends on them
		// and a stubbed 1×1 would make every assertion here vacuous.
		if (path.startsWith('/d/')) {
			return route.fulfill({ contentType: 'image/png', body: WIDE_PNG });
		}
		if (path.endsWith('/comments') && route.request().method() === 'POST') {
			const body = route.request().postDataJSON() as Record<string, unknown>;
			recorder.posted.push(body);
			return route.fulfill({
				status: 201,
				json: comment({
					id: 'new-1111-4111-8111-111111111111',
					body: body.body,
					region: body.region
				})
			});
		}
		if (path.endsWith('/comments')) {
			return route.fulfill({ json: options.comments ?? [] });
		}
		if (path === '/assets' || path === '/search') {
			return route.fulfill({
				json: { items: [asset()], total: 1, offset: 0, ranked: false, did_you_mean: null }
			});
		}
		if (path === '/me') return route.fulfill({ json: person() });
		if (
			path === '/fields' ||
			path === '/categories' ||
			path === '/search/facets' ||
			path === '/people'
		) {
			return route.fulfill({ json: [] });
		}
		if (path.endsWith('/download-options')) {
			return route.fulfill({
				json: { original_available: true, media_class: 'image', conversions: [] }
			});
		}
		if (path.endsWith('/usage-options')) {
			return route.fulfill({
				json: {
					channels: [],
					territories: [],
					default_channel: 'internal',
					default_territory: 'WORLD'
				}
			});
		}
		if (path.startsWith('/assets/')) return route.fulfill({ json: asset() });
		return route.fulfill({ json: {} });
	});

	return recorder;
}

/** Opens the lightbox on the first asset. */
async function lightbox(page: Page) {
	await page.goto('/assets');
	await page.getByRole('gridcell').first().click();
	await page.keyboard.press('Enter');
	const dialog = page.getByRole('dialog');
	await expect(dialog).toBeVisible();
	// The image must have loaded, or the overlay has no natural size to measure against.
	await expect(dialog.locator('img').first()).toBeVisible();
	await page.waitForFunction(() => {
		const img = document.querySelector('dialog img');
		return img instanceof HTMLImageElement && img.naturalWidth > 0;
	});
	return dialog;
}

/** Where the picture actually is, inside the overlay — computed the way the component should. */
async function contentBox(page: Page) {
	return page.evaluate(() => {
		const img = document.querySelector('dialog img');
		const host = document.querySelector('dialog [role="group"]');
		if (!(img instanceof HTMLImageElement) || !(host instanceof HTMLElement)) {
			throw new Error('no image or overlay');
		}
		const box = img.getBoundingClientRect();
		const scale = Math.min(box.width / img.naturalWidth, box.height / img.naturalHeight);
		const width = img.naturalWidth * scale;
		const height = img.naturalHeight * scale;
		return {
			left: box.left + (box.width - width) / 2,
			top: box.top + (box.height - height) / 2,
			width,
			height,
			elementHeight: box.height,
			letterboxed: Math.abs(box.height - height) > 2
		};
	});
}

test('this layout does not letterbox, which is why the next test forces it', async ({ page }) => {
	// Written first as a guard, and it immediately earned its keep by failing. The lightbox uses
	// `max-w-full max-h-full object-contain`, under which the *element* shrinks to the image rather than the
	// image being contained inside a fixed element — so the element box and the content box coincide and there
	// are no bands.
	//
	// That means every coordinate assertion in this file would pass whether the component normalised against
	// the picture or against the element. Recorded rather than quietly relied upon, because the maths is still
	// the right maths — a fixed-size box is the commoner pattern and one CSS change away — and the test below
	// forces that layout so the defence is actually exercised.
	await connect(page);
	await lightbox(page);
	const box = await contentBox(page);
	expect(box.letterboxed).toBe(false);
	expect(box.width / box.height).toBeCloseTo(2, 1);
});

test('a drag lands correctly even when the image is letterboxed', async ({ page }) => {
	// The case the letterbox maths exists for, forced: a fixed-size element with `object-contain` puts a 2:1
	// picture in a squarer box, leaving bands above and below. Normalising against the element would put this
	// drag's y at roughly 0.35 rather than 0.25 — so if the component measured the wrong box, this is where it
	// would show.
	const recorder = await connect(page);
	const dialog = await lightbox(page);
	// Injected rather than changed in the component: the point is that the *maths* is right for both layouts,
	// and pinning the component to one of them would make the defence untestable rather than unnecessary.
	//
	// Fixed pixels, and square. The first attempt used `80vw`/`70vh`, which on the default 1280×720 viewport
	// is 1024×504 — a ratio of 2.03, near enough the picture's own 2:1 that there were no bands at all and the
	// test failed its own precondition. A 2:1 image in a 400×400 box letterboxes by 100px top and bottom,
	// which is unmistakable.
	await page.addStyleTag({
		content:
			'dialog img { width: 400px !important; height: 400px !important; max-width: none !important; max-height: none !important; }'
	});
	// The overlay remeasures on resize; give the observer a frame.
	await page.waitForTimeout(150);

	const box = await contentBox(page);
	expect(box.letterboxed).toBe(true);
	expect(box.height).toBeLessThan(box.elementHeight - 2);

	await dialog.getByRole('button', { name: 'Annotate' }).click();
	await page.mouse.move(box.left + box.width * 0.25, box.top + box.height * 0.25);
	await page.mouse.down();
	await page.mouse.move(box.left + box.width * 0.75, box.top + box.height * 0.75, { steps: 8 });
	await page.mouse.up();

	await dialog.getByPlaceholder('What about this part?').fill('the middle');
	await dialog.getByRole('button', { name: 'Add note' }).click();
	await expect.poll(() => recorder.posted.length).toBe(1);

	const region = recorder.posted[0].region as number[];
	expect(region[0]).toBeCloseTo(0.25, 2);
	expect(region[1]).toBeCloseTo(0.25, 2);
	expect(region[2]).toBeCloseTo(0.5, 2);
	expect(region[3]).toBeCloseTo(0.5, 2);
});

test('a drag over the middle of the picture is the middle of the picture', async ({ page }) => {
	const recorder = await connect(page);
	const dialog = await lightbox(page);
	await dialog.getByRole('button', { name: 'Annotate' }).click();

	const box = await contentBox(page);
	// A quarter in from each edge, so the expected answer is exactly [0.25, 0.25, 0.5, 0.5].
	await page.mouse.move(box.left + box.width * 0.25, box.top + box.height * 0.25);
	await page.mouse.down();
	await page.mouse.move(box.left + box.width * 0.75, box.top + box.height * 0.75, { steps: 8 });
	await page.mouse.up();

	await dialog.getByPlaceholder('What about this part?').fill('this quarter is wrong');
	await dialog.getByRole('button', { name: 'Add note' }).click();
	await expect.poll(() => recorder.posted.length).toBe(1);

	const region = recorder.posted[0].region as number[];
	// Within a couple of pixels' worth. Normalising against the element instead would put y at roughly 0.35
	// and h at roughly 0.3 for this fixture — far outside this tolerance, which is the point of the numbers.
	expect(region[0]).toBeCloseTo(0.25, 2);
	expect(region[1]).toBeCloseTo(0.25, 2);
	expect(region[2]).toBeCloseTo(0.5, 2);
	expect(region[3]).toBeCloseTo(0.5, 2);
});

test('what goes on the wire is fractions, never pixels', async ({ page }) => {
	const recorder = await connect(page);
	const dialog = await lightbox(page);
	await dialog.getByRole('button', { name: 'Annotate' }).click();

	const box = await contentBox(page);
	await page.mouse.move(box.left + 10, box.top + 10);
	await page.mouse.down();
	await page.mouse.move(box.left + box.width * 0.6, box.top + box.height * 0.6, { steps: 6 });
	await page.mouse.up();
	await dialog.getByPlaceholder('What about this part?').fill('here');
	await dialog.getByRole('button', { name: 'Add note' }).click();
	await expect.poll(() => recorder.posted.length).toBe(1);

	const region = recorder.posted[0].region as number[];
	for (const value of region) {
		expect(value).toBeGreaterThanOrEqual(0);
		expect(value).toBeLessThanOrEqual(1);
	}
	// And it fits inside the picture, which is what the server's constraint demands.
	expect(region[0] + region[2]).toBeLessThanOrEqual(1.0001);
	expect(region[1] + region[3]).toBeLessThanOrEqual(1.0001);
});

test('a click that is not a drag creates nothing', async ({ page }) => {
	// Otherwise every stray click opens a note box over a one-pixel region — which the server would refuse
	// anyway for having no extent, so the failure would arrive as an error rather than as nothing happening.
	const recorder = await connect(page);
	const dialog = await lightbox(page);
	await dialog.getByRole('button', { name: 'Annotate' }).click();

	const box = await contentBox(page);
	await page.mouse.move(box.left + box.width / 2, box.top + box.height / 2);
	await page.mouse.down();
	await page.mouse.up();

	await expect(dialog.getByPlaceholder('What about this part?')).toHaveCount(0);
	expect(recorder.posted).toHaveLength(0);
});

test('existing annotations are drawn where they were put, and say what they are', async ({
	page
}) => {
	await connect(page, {
		comments: [
			comment({
				id: 'a1111111-1111-4111-8111-111111111111',
				region: [0.1, 0.2, 0.3, 0.4],
				body: 'crooked'
			}),
			// A comment with no region is not an annotation and must not become a box at the origin.
			comment({ id: 'b1111111-1111-4111-8111-111111111111', region: null, body: 'approved' })
		]
	});
	const dialog = await lightbox(page);

	const marks = dialog.getByRole('button', { name: /Ada:/ });
	await expect(marks).toHaveCount(1);
	// The label carries who and what, so a screen reader hears the note rather than "region 1".
	await expect(marks.first()).toHaveAttribute('aria-label', /Ada: crooked/);
	await expect(dialog.getByText('1 note on this picture')).toBeVisible();

	// Placed against the picture, not the element.
	const box = await contentBox(page);
	const mark = await marks.first().boundingBox();
	expect(mark).not.toBeNull();
	expect(mark!.x).toBeCloseTo(box.left + box.width * 0.1, 0);
	expect(mark!.y).toBeCloseTo(box.top + box.height * 0.2, 0);
	expect(mark!.width).toBeCloseTo(box.width * 0.3, 0);
	expect(mark!.height).toBeCloseTo(box.height * 0.4, 0);
});

test('selecting a mark shows its words', async ({ page }) => {
	await connect(page, {
		comments: [comment({ region: [0.2, 0.2, 0.4, 0.4], body: 'the crop cuts the logo' })]
	});
	const dialog = await lightbox(page);

	await dialog.getByRole('button', { name: /Ada:/ }).click();
	await expect(dialog.getByText('the crop cuts the logo')).toBeVisible();
	// Read-only here: editing lives in the comment thread, where the replies and the status are.
	await expect(dialog.getByRole('textbox')).toHaveCount(0);
});

test('the annotation surface says that drawing needs a pointer', async ({ page }) => {
	// The honest statement rather than a role that claims more. Reading and focusing annotations works from the
	// keyboard — they are buttons; *creating* one is a drag, and no attribute changes that.
	await connect(page);
	const dialog = await lightbox(page);
	await dialog.getByRole('button', { name: 'Annotate' }).click();

	await expect(dialog.getByText('A pointer is needed for this')).toBeVisible();
	await expect(dialog.getByRole('group', { name: /requires a pointer/ })).toBeVisible();
});

test('the annotation overlay has no axe violations', async ({ page }) => {
	await connect(page, {
		comments: [
			comment({ id: 'a1111111-1111-4111-8111-111111111111', region: [0.1, 0.1, 0.2, 0.2] }),
			comment({
				id: 'b1111111-1111-4111-8111-111111111111',
				region: [0.5, 0.5, 0.3, 0.3],
				body: 'and here'
			})
		]
	});
	const dialog = await lightbox(page);
	await dialog.getByRole('button', { name: 'Annotate' }).click();
	await expect(dialog.getByRole('button', { name: /Ada:/ }).first()).toBeVisible();

	const results = await new AxeBuilder({ page }).withTags(WCAG_21_AA).analyze();
	const detail = results.violations
		.map((v) => `${v.id}: ${v.nodes.map((n) => n.target.join(' ')).join(', ')}`)
		.join('\n');
	expect(results.violations, `axe violations:\n${detail}`).toEqual([]);
});
